      "Hoje, 12/10/2021, comemoramos a Padroeira do Brasil: Nossa Senhora Aparecida. Nesta bela homilia, Frei Rui explica a história e o caráter religioso de Maria, nossa Mãe e Mãe de Deus. De Aparecida, nossa Padroeira e protetora.",
