      "Frei Rui Depiné o.f.m.",
      "Foi em outubro de 1717. A cidade de Aparecida não existia. Apenas alguns casebres, choupanas de pescadores, alguns barracos de famílias bem pobres se estendiam ao longo do rio Paraíba.",
