      "Tinham pescado o corpo de uma imagem quebrada.",
      "Recolheram, colocaram na canoa e continuaram a pescar.",
      "Pouco depois colheram também a cabeça da imagem. Ficaram espantados. Um rio tão longo e profundo. Quem navega o Paraíba sabe que é longo e profundo.",
      "Terminado o trabalho, eles levaram a imagem para casa. Fizeram um pequeno altar.",
      "A noite a vizinhança reunia-se naquele barraco para rezar o terço.",
      "Começou a acontecer coisa estranha, coisa sobrenatural. Gente doente, ficava boa. Gente brigada, voltava a fazer a paz. Quem bebia, deixava de beber. Quem roubava, deixava de roubar. Quem não acreditava, acreditava.",
      "Todo mundo dizia que a Santa era milagrosa.",
      "Se fez uma Capelinha e deram o nome de Aparecida. Todo mundo agora queria morar bem perto da Imagem. Começaram a construir suas casas.",
      "A Capelinha é o novo Santuário do mundo e o lugar de uma grande cidade. Nossa Senhora Aparecida é a padroeira do Brasil.",
      "Antes de terminar, eu ainda perguntaria.",
      "Quem é Nossa Senhora Aparecida?",
      "Deus tem os seus caminhos para se mostrar.",
      "Será que é um ser humano daqui deste mundo?",
      "Quem fez esta imagem?",
      "Onde foi feita.",
      "Quando foi feita.",
