      "O Frei Rui era um estudioso. Na sua humildade não ostentava seus sólidos conhecimentos. Falava de maneira simples para que pudéssemos compreender melhor sua mensagem. Mas era um sábio. Filósofo e Teólogo, Frei Rui falava várias línguas (inglês, francês, italiano, alemão, espanhol, latim). Lia muito. Poderia ter sido um professor. De certa forma, era um professor pois ensinou muito para todos: com sua palavra e com seu exemplo de vida. Neste texto, Frei Rui discorre sobre Ética. Nosso professor, Frei Rui, nos lembra, mais uma vez, o que é importante na vida.",
