      "Ética",
      "Frei Rui Guido Depiné o.f.m.",
      "É a arte de bem viver.",
      "É a arte de fazer bem feitas todas as coisas.",
      "É a arte de falarmos todas as palavras com sentido.",
      "É a arte de pensarmos de forma justa e elevada.",
      "Ética é uma decisão livre de darmos à vida um sentido bom.",
      "A ética está ligada a uma concepção de vida que faz do relacionamento humano uma convivência de bem-estar.",
      "Está calcada sobre os valores fundamentais da vida que se manifestam no comportamento em todas as circunstâncias da vida. O bem, o bom, o belo, o justo, a virtude são a essência da ética.",
      "A ética é um modo de ser. É um estilo de vida da pessoa. É um horizonte existencial a ser alcançado. Ethos em grego é moradia. A casa para morar deve ser boa, aconchegante, limpa, em ordem.",
      "Ninguém pode fazer tudo o que quer.",
