      "Dois de novembro de 2021. Dia de Finados. Quanta lembrança e quanta dor nesta data. Nós vamos aos cemitérios, lembrando os entes queridos que já partiram. Mas as palavras do Frei Rui sempre nos consolam e nos fazem refletir. Para nós, Católicos, Cristãos, a morte não existe. Cristo ressuscitou e com Ele, um dia, estaremos no Paraíso.",
      "Paz e Bem!",
