      "Frei Rui Guido Depiné o.f.m.",
      "2011",
      "Saudação Franciscana",
      "Um dia esta vida será o depois desta vida.",
      "A morte num determinado momento irá bater na porta da nossa casa. Nos fará chorar porque vai nos separar. É um fenômeno universal que atinge todas as formas de vida.",
      "A vida não só convive com a morte, não só pensa na morte – fala da morte – não só conhece a morte, mas, passa obrigatoriamente pela morte. O tempo se encarrega deste acontecimento.",
