      "Convém lembrar que a morte não está longe de nós, fora de nós, distante de nós, mas dentro de nós. A morte coabita com a vida. Disse um sábio que a vida e a morte são como duas linhas de trem: caminham paralelas, mas no final se encontram. Disse outro sábio que a morte não tem preferência por ninguém, porque está todo mundo na vez.",
      "Disse o poeta que a vida é como a poeira da estrada: o vento leva. Não há nada neste mundo que possa impedir o final desta vida. Nem fortuna – poder – fama – prestígio, nem sabedoria e nem espiritualidade.",
      "Podemos pensar em Deus noite e dia. Podemos saber a Bíblia de cor. A morte nos espera em qualquer ponto do planeta, em qualquer canto deste mundo. E por melhor que seja alguém, chega o dia em que ele há de faltar. Seja o pai, a mãe, o irmão, a irmã, o filho, a filha, um parente ou um amigo. Um dia ele há de faltar.",
      "Como, quando, onde haveremos de fechar os olhos para sempre, só Deus o sabe.",
