      "São chamados sábios – magos – sinônimo de pesquisadores – astrônomos.",
      "Para tomar esta decisão só podiam ser muito sábios.",
      "Sábio é aquele que procura entender sempre melhor o sentido último das coisas, e crescer.",
      "Como sábios, pesquisadores, cientistas, eles viram uma estrela diferente e isto os impressionou. Ver estrelas não significa muita coisa mas é preciso olhar para cima. Muita gente só olha para baixo.",
