      "Se aqueles três Reis enxergaram o horizonte, o firmamento, a estrela – a luz; isto significa que eles não viviam apenas de cabeça baixa, presos com as coisas deste mundo, como os animais que quando encontram o capim, a pastagem ou um cocho de comida, encontraram tudo o que precisavam neste mundo.",
      "Aqueles três Reis, três sábios olharam para além do seu palácio, dos seus domínios – eles entendiam que o segredo, que a chave da vida estava para além – estava em outro mundo. Eles sabiam que tudo aquilo que eles possuíam não era tudo. Faltava algo – o mais importante – a essência das coisas e esta só seria encontrada se eles tivessem a coragem de sair do palácio – de não serem escravos de um pingo de bens, de pôr-se a caminho – deserto a fora – renunciar a tudo, e eles o fizeram. Por isto encontraram a estrela, a gruta, o menino – José e Maria, e eles mesmos se tornaram uma espécie de estrela para todos os homens de boa vontade.",
      "A salvação está para além das coisas que nos cercam."
