      "Caderno 19",
      "Homilia 29",
      "Sexta Feira Santa",
      "3 horas da tarde.",
      "Último dia de vida de Jesus Cristo neste mundo, na Palestina, Nazaré, Galileia, Cafarnaum, no meio do seu povo, junto de seus amigos e seguidores.",
      "Nenhum ser humano jamais amou tanto este mundo como Ele. Amou os seus até o fim. Até o último suspiro na Cruz. Até a morte.",
      "Sua via terrena se constitui no que há de mais elevado, grandioso, sagrado nesta terra.",
      "Suas palavras, seus gestos, sua obra, sua doutrina são lembradas e seguidas por multidões",
      "Sua prisão, seu julgamento, seu processo, sua sentença, sua condenação, sua crucificação foi, é e será sempre a maior injustiça, o maior engano, a maior farsa de toda história da humanidade, de todos os tempos e lugares.",
      "Blaise Pascal diz: “Este Cristo na cruz será um eterno tormento enquanto o homem não lhe devolver sua inocência. ”",
      "Sua Ressurreição deixa o mundo pagão - do pecado, da descrença, da incredulidade, da insanidade - confuso e perplexo. Ele, apesar de morto, não foi aniquilado. Ele não desapareceu. Não foi sepultado para sempre. Ele continua mais presente agora que antes.",
      "E se transformou numa fonte universal de certezas e esperanças e presença humana. Muito mais do que isto, de promessas bíblicas que foram cumpridas no seu próprio corpo.",
      "Este acontecimento que estamos celebrando nesta hora.",
      "Hoje era o dia da morte do Cordeiro Pascal entre o povo judeu, para comemorar amanhã (sábado) a Páscoa Judaica, a libertação das mãos dos Faraós – da escravidão do Egito. Cristo se deixa matar neste mesmo dia. Ele substitui o cordeiro. Ele mesmo é comparado a um cordeiro que se deixa levar ao matadouro sem balir – sem abrir a boca.",
      "Nenhum ser humano jamais ofereceu um ideal de vida tão elevado e profundo como Jesus Cristo – suas lições, seus ensinamentos, são inesgotáveis."
