      "Caderno 19",
      "Homilia 33",
      "Cristo Rei",
      "O povo judeu ficou desapontado, decepcionado – em sua expectativa de imaginar que o Cristo seria um personagem poderoso, forte, dominador, invencível, capaz de libertar o povo do julgo romano.",
      "Contrariando toda esta mensagem de um Messias político, nasce o Cristo muito pobre – numa gruta – numa estrebaria – sem nome – sem glória – sem recursos – sem a fama dos soberanos deste mundo.",
      "No entanto, é ali no deserto, no anonimato que começa o seu reinado diferente de todos os reinos terrestres e temporais.",
      "A libertação política de Israel não acontece, e o Cristo é rejeitado, o povo decepcionado e rebela e exclama: “Não queremos que ele reine sobre nós”.",
