      "Homilia 38",
      "Natal",
      "Músicas de Natal, mensagens de Natal, cartões de Natal, presentes de Natal, presépios, pinheirinhos, velas de Natal, pisca-piscas coloridos de Natal, tanta coisa que tem um certo sentido de Natal – mas tudo isto é vida morta, vida artificial – se Deus não estiver presente no meio destes símbolos; porque são arranjos que depois são encaixotados, guardados ou talvez até jogados fora.",
