      "Homilia 7",
      "Mãe",
      "Que essa Missa seja uma homenagem a nossas mães. Por tudo quanto fez nossa mãe – por tudo quanto é nossa mãe.",
      "Não há maneira mais elevada de festejarmos o seu nome do que por-nos diante de Deus e oferecer-lhe a vida de nossa mãe com tudo aquilo que ela representa para nós.",
      "Canções",
      "Pensamentos",
      "Homenagens",
      "Flores",
      "Palavras",
      "Presentes",
      "Procuremos viver como ela pediu que convivêssemos.",
      "Ser mãe é muito mais do que apenas morar dentro de uma casa.",
      "- do que embalar uma criança num berço.",
      "É partilhar a sua vida – a vida inteira para que o outro chegue à plenitude tanto física, defeituosa ou doente - como espiritual, que saiba ir bem desta vida material que não leve falta de nada -  moral que tenha princípios e dignidade – psíquico, que seja bem equilibrado, ajustado e feliz.",
      "Ser mãe não é apenas dar a vida mas ensinar a viver.",
      "É amar os filhos mesmo quando estes se tornam rebeldes ou indiferentes.",
      "É amar o esposo mesmo quando este trai ou despreza ou não cumpre seus deveres.",
      "Ser mãe é repartir a vida minuto por minuto – dia a dia. A vida inteira assim como se reparte o pão sobre a mesa.",
      "É repartir da vida. Com os filhos que nasceram, com o esposo em quem um dia prometeu amor e fidelidade.",
      "Poucos se dão conta do que é uma mãe.",
