      "O mar da Galileia provoca contínuas tempestades por causa do seu clima e encontro de massas frias e quentes.",
      "O mar da Galileia será famoso por sua indústria de pesca. Fontes sulfurosas perto da praia atraia muitas pessoas enfermas. Algumas cidades bíblicas estão situadas a beira-mar como Cafarnaum, Betsaida, Magdala, Corazim, Caná e Tiberíades. Mais ou menos 9 cidades. 15 mil habitantes cada uma.",
