      "Ficavam a espera de algum sina da vida. Enquanto as coisas se aclarassem, eles retomaram o seu ofício anterior – a pesca era o meio de vida – o sustento – o ganho. Ainda que fosse um trabalho humilde depois de tantos acontecimentos trágicos, era preciso sobreviver.",
      "É a última vez que eles vão pescar juntos.",
      "Depois eles seguirão a risca a incumbência da evangelização até a morte."
