      "Homilia 12",
      "II Domingo do Advento",
      "O Evangelho de hoje menciona dois grandes profetas – Isaías e João Batista.",
      "Isaías diz – “Eis que eu envio meu anjo ante a tua face o qual preparará o teu caminho diante de ti. ”",
