      "A Bíblia não é para aquele que tem tudo, para aqueles que se bastam a si mesmos, para aqueles que são autossuficientes, para aqueles que pensam que vão viver sempre aqui nesta terra, para aqueles que fazem deste mundo sua última morada.",
