      "O ambiente da Igreja primitiva composta de apóstolos, Nossa Senhora, por discípulos e muitos seguidores é um ambiente de medo, um ambiente de desconfiança, um ambiente de desânimo e incertezas.",
      "O Cristo que desencadeou esta situação agora desaparece, se ausenta deste mundo. Os apóstolos que são a cabeça da Igreja, ficam sozinhos, desamparados e entregues à própria sorte.",
      "Neste domingo os discípulos estão numa sala, a portas fechadas por medos dos judeus.",
      "Eles tinham uma certa base para terem medo. Eles tinham visto o que acontecera com o Cristo – Eles sabiam que Pilatos era capaz de tudo. Eles sabiam que Herodes era um sanguinário. Eles sabiam que multidões tudo fizeram para matar o Nazareno.",
      "Ter medo da vida e da morte é algo natural do ser humano.",
      "Mas depois deste domingo – quando o Cristo lhes aparece e lhes diz “Recebei o Espírito Santo”, eles se tornam homens livres de tudo – corajosos – destemidos – desafiadores – de uma fé inquebrantável – abrem as portas – fazem pregações em praças públicas – enfrentam as maiores autoridades tanto da Judeia como de Roma, enfrentam a fome, a perseguição, o castigo, os açoites, a prisão – e a própria morte – eles se tornam quase deuses.",
