      "Pretendemos nós entender o mistério da Santíssima Trindade. É uma tarefa impossível porque o homem é pequeno demais para entender tudo. Querer entender o mistério da Santíssima Trindade é assemelhar-se àquela criança que sentada na praia com uma concha na mão, queria pôr o mar dentro de um buraco que fizera na areia.",
