      "Pe. Roque mandou recado que eu estivesse presente nesta celebração. Atendendo o convite. Aqui estou.",
      "As circunstâncias da vida nos irmanaram mais uma vez: uma grande festa.",
      "Autoridades, gente da cidade, dos bairros, gente do campo, visitantes, festeiros, amigos, devotos.",
      "Estamos em torno deste altar conscientes de que a história humana é também marcada pela história divina. Deus pisou este mesmo chão que nós pisamos, morou numa casa como nós. E Deus pede algo de nós e ninguém pode tirar o corpo fora.",
      "Estamos aqui numa demonstração coletiva de interesse, de integração, colaboração, cooperação, de esforço, de cuidado para que os valores materiais, sociais, culturais e religiosos sejam à base de nossas famílias, na caminhada por este mundo a fora. No fim da nossa vida Deus não vai nos perguntar quantos imóveis tivemos. Deus vai nos perguntar o que fizemos com a nossa vida e seu Evangelho.",
      "Mais uma vez celebramos a festa do Senhor Bom Jesus, Padroeiro desta cidade, unindo os sentimentos de religiosidade e de confraternização. E isto é muito bom.",
      "A festa do Padroeiro é muito mais do que uma festa externa, de mera recreação e arrecadação, por mais organizada que seja e por melhor que seja seu resultado.",
      "Ela é diferente do que uma festa a beira de um autódromo, ou numa hípica ou que uma festa de carnaval ou partida de futebol, etc.",
      "Festa do Padroeiro deve refletir a vida do Padroeiro – a história do Padroeiro – o pensamento do Padroeiro, a doutrina no Padroeiro – no caso aqui é Bom Jesus – Filho de Deus.",
      "Neste sentido esta festa deve ser a expressão da convivência humana – do bem estar entre todos, a expressão da amizade – da união – da reconciliação – do perdão (aliás Senhor Bom Jesus dos Perdões).",
