      "Os discípulos estão reunidos e falam sobre os últimos acontecimentos que envolveram a vida de Jesus Cristo, sua condenação, cruxificação e Páscoa. Jesus se apresenta e lhes diz: “A paz esteja convosco. ” Saudação muito antiga e muito comum entre os Judeus. Jesus está de volta. Eles ouvem a Sua voz. Eles O veem com seus olhos, Ele está no meio deles.",
