      "Leva Jesus para Jerusalém na parte mais alta do templo e diz. “Se és Filho de Deus, atira-te daqui para baixo porque os anjos te protegerão – Te levarão na palma das mãos”.",
      "Jesus respondeu: “Não tentarás o Senhor teu Deus”. E o Diabo sumiu. Devemos entender isto não ao pé da letra mas como a força do mal que age em nós.",
