      "Homilia 117",
      "Cruxificação",
      "O Evangelista Marcos descreve a tarde da cruxificação dizendo que as trevas cobriram toda terra e Jesus do alto da cruz gritou “Meu Deus, Meu Deus, por que me abandonaste. ” Alguns achavam que Jesus estivesse invocando o Profeta Elias.",
      "No auge da dor e da agonia Jesus pede água dizendo aos próprios ímpios “Tenho sede”. Um dos soldados fez uma mistura de água com vinagre, bebida que os soldados tomavam enquanto montavam guarda e molhando uma esponja fixada na ponta de uma lança molhou a boa de Jesus.",
      "Não suportando tanta dor Jesus fala suas últimas palavras “Tudo está consumado” e inclinando a cabeça morreu.",
      "O centurião romano em vez de se alegrar, se assusta e sente algo diferente. O centurião romano exclama: “Verdade, este homem era o Filho de Deus”.",
      "Duas horas depois da morte de Jesus começa o sábado que coincidia com a Páscoa Judaica.  O dia para os Judeus não terminava a meia noite mas com o pôr do sol. O corpo de um cruxificado era considerado maldito e contaminava a Páscoa Judaica. O corpo contaminava. O crime não. O crime, a injustiça, a violência, a desumanidade.",
      "José de Arimateia pede a Pilatos o corpo de Jesus. Os cruxificados eram observados se estavam mortos ou não. Se não estavam, lhes eram quebradas as pernas com uma barra de ferro. Como Jesus estava morto não lhes quebraram as pernas mas um soldado transpassou seu peito com uma lança.",
