      "Homilia 119",
      "Seguidores abandonam Jesus",
      "A quem iremos, Senhor",
      "Domingo passado o evangelista São João mostrava como muitos seguidores e simpatizantes do Cristo chegaram a conclusão que sua doutrina, ensinamentos eram impossíveis de serem praticados. Por isto muitos se desencantaram e o abandonaram. Por fim sobraram somente os apóstolos – naquele acontecimento Jesus toma a palavra e dizia a eles: “Se vocês quiserem ir embora, vão”. Jesus ficaria sozinho. Pedro tomando a palavra retrucou: “Se nós te abandonarmos a quem iremos, Senhor”. E eles foram fieis até o fim. E Pedro disse a Jesus. Sabemos que tu és o Cristo, o Filho de Deus. E só tu tens palavra de vida eterna.",
      "Ao longo de sua vida Jesus teve muitos amigos e muitos inimigos também. Amigos o acolheram – o hospedaram em sua casa. O seguiram e fizeram dele a base da vida.",
      "Ao longo de dois mil anos quantas pessoas o recordaram, o imitaram na busca da verdade, da justiça – do perdão – da paz e da convivência humana.",
      "Quanta gente também indiferente, desinteressada, agnóstica, não sabe nada a seu respeito ou pior ainda o menosprezo ou acha ser ópio do povo.",
      "No Evangelho de hoje mais conflitos para o Cristo. Ele é vigiado por fariseus e Doutores da Lei.",
      "Jesus transgride a lei. Não lavar as mãos antes das refeições era violar as tradições religiosas judaicas (farisaicas).",
      "No tempo de Jesus tudo o que se comprava no mercado, na rua, na praça pública, comércio, deveria ser purificado porque poderia estar contaminado pelo contato de gente impura – como o povo da terra – agricultores, estrangeiros, pagãos, doentes, pobres, prostitutas, etc.",
      "Jesus passa por cima destas convenções humanas e diz que o que contamina o homem é o que está na cabeça, o julgamento leviano, a hipocrisia, a mentira, o ódio, a vingança, o olho por olho, a discriminação, o preconceito, a injustiça.",
      "Jesus ao longo de sua vida teve muitos inimigos que o acusaram de tanto que o prenderam – o acusaram – o mataram.",
      "Não foi fácil para Jesus ser Jesus e revelar porque veio.",
      "Assim também é nossa vida de cada dia. Não é fácil dar-lhe um sentido sempre bom porque vivemos cercados de tantos males que nos desestruturam. Costumo dizer que o mundo moderno não favorece a vivência do cristianismo. Favorece mais, mais uma vivência pagã. Mas o lugar onde podemos fazer esta experiência do Cristianismo é onde estamos e vivendo."
