      "PUBLICADO EM 29 DE SETEMBRO DE 2024",
      "Homilia 127",
      "Deus na nossa caminhada",
      "Todos nós gostaríamos que Deus fizesse parte da nossa caminhada por este mundo a fora. De dia – de noite. Que Deus nos abençoasse em nossa vida particular. Que Deus nos abençoasse em nossa família, em nossa vida profissional, em nosso relacionamento humano.",
