      "Epifania – A visita dos Reis Magos",
      "É uma história encantadora ligada ao Natal. É de grande beleza e valor e sabedoria. Três homens vêm de longe a procura da Gruta de Belém para ver o menino recém-nascido e guiados por uma estrela.",
      "Este menino que nasceu num lugar escondido de uma pequena cidade sem importância não se limita a uma pequena geografia, gruta, Belém, Palestina, Oriente, mas se projeta no mundo inteiro como a luz do sol.",
