      "Eles queriam encontrar o próprio Deus ainda que em forma de uma criança divina. Eles deveriam conhecer as Escrituras Sagradas e o anúncio dos Profetas.",
      "Para tomar esta grande decisão só poderiam ser muito sábios.",
      "Sábio não é aquele que sabe tudo porque ninguém sabe tudo. Sábio é aquele que quer compreender o sentido último da vida. Sábio é aquele que quer aprender sempre mais e crescer. E eles queriam crescer.",
      "Como sábios, pesquisadores, cientistas e astrônomos; eles viram uma estrela diferente no firmamento. Ver estrelas não significa muita coisa. Mas é preciso olhar para cima. Quem olha só para baixo não vê estrelas.",
      "E muita gente só olha para baixo.",
      "Na sua lida de cientistas eles não viram apenas uma estrela, mas, eles viram para além daquela estrela. Eles viram através da estrela um sinal no céu. Eles viram uma mensagem, um recado que muita gente não viu.",
      "Herodes não viu. Pilatos não viu. Anás, Caifás e tantos Sumos Sacerdotes não viram, mesmo os moradores de Belém. Multidões não viram, ou não quiseram ver e não verão jamais, não porque não tivessem olhos, mas porque não tinham alma, não tinham coração para ver e nem ouvidos para ouvir. Aqueles três reis não eram escravos das coisas materiais.",
      "Por isto deixaram seu Palácio, suas riquezas, todos os seus bens e entenderam que a sabedoria maior da vida vinha do alto e tudo o que eles possuíam não eram tudo, mas, alguma coisa apenas, e que o mais fundamental só seria encontrado fora do Palácio, se eles tivessem a coragem de sair do seu Palácio, enfrentar o deserto, a caminhada de mais de 400 km.",
      "Assim eles encontraram a estrela – Maria, José, a Gruta, o menino, os pastores e eles se tornaram uma espécie de estrela de primeira grandeza para todos os homens de boa vontade.",
      "A salvação eterna vem da Gruta de Belém."
