      "Sexta Feira Santa 2006",
      "O mundo cristão celebra hoje o mistério do sofrimento humano, da paixão e morte de Jesus Cristo na cruz, no alto do Calvário. Morte decretada pelo Sinédrio, tribunal supremo de Jerusalém. Mostra o Drama do Calvário como foi crescendo a trama, a conspiração contra Jesus de Nazaré.",
