      "Uma oposição cada vez mais forte vai envolvendo as mais altas autoridades de Jerusalém e multidões gritam pela morte de Jesus. Até Domingo de Ramos, há 4 dias atrás Ele era saudado, aplaudido, admirado como Salvador do mundo, como Messias, como Filho de Deus, como o Mestre de Israel, de tal forma que muita gente estendia sua túnica, suas vestes, ornamentavam o caminho.",
      "Com ramos de oliveira, folhas de palmeiras e flores e gritavam ainda mais forte “Bendito aquele que vem em nome do Senhor. Hosana nas alturas. ”",
