      "Assim Jesus perdeu o direito à vida. Sumariamente julgado, foi condenado e cruxificado. Os grandes deste mundo imaginavam que matar Jesus seria cruxificá-Lo, transpassa-Lo com a lança num cadáver. Matar Jesus seria sepultá-Lo e pôr lhe uma pedra grande sobre a sepultura. Vigiar seu túmulo. E nunca mais seria visto.  Ninguém falaria seu nome ou acreditaria na sua História, na sua doutrina.",
      "Só restava agora celebrar, dentro do mundo das trevas, a sua derrota, o seu aniquilamento.",
      "Mas, madrugada de domingo, o túmulo emprestado de José de Arimateia, está vazio. Os lençóis de linho dobrados – os guardas em fuga.",
