      "Diz o Evangelho de hoje: Que Deus enviou Seu Filho ao mundo não para condenar o mundo para salvar o mundo. A palavra forte e chave é a Salvação. Salvar significa não perder a vida. Preservar a vida. Significa continuar vivo.",
