      "Homilia 133",
      "Proximidades da Páscoa",
      "Jesus vai ao Templo de Jerusalém. Para o bom judeu – o templo é a Casa De Deus, é o Santuário de Deus. É a morada de Deus. É o lugar mais santo. Fica em Jerusalém. Jerusalém é conhecida como a Cidade Santa em função do Templo Sagrado. No Templo são feitas as celebrações religiosas. É feita a leitura dos livros sagrados, sua interpretação pelos rabinos, pelos Sumos Sacerdotes, pelos Mestres. São lembrados os Patriarcas, os Profetas, o Povo de Deus na história. No Templo é prestado um culto de louvor. Feitas orações. Para o Templo convergem pessoas peregrinas do mundo inteiro.",
