      "São Lucas – evangelista e médico, descreve os últimos passos da vida de Jesus após a Páscoa. Jesus repete o que já tinha anunciado. De que Ele seria morto, mas, ressuscitaria, e que em seu nome muitos se converteriam e alcançariam o perdão de todos os pecados.",
