      "Jesus pressentindo sua volta para o Pai – levou os discípulos até Betânia, terra de Lázaro, Marta e Maria, uma família predileta de Jesus. Como tantas vezes fizera, levanta as mas mãos e abençoa seus amigos. É a última vez de forma visível.",
