      "Eles se entregam de corpo e alma na grande tarefa da Evangelização. “Sereis minhas testemunhas até os confins do mundo”. Tanto na leitura dos Atos dos Apóstolos – como no Evangelho de São Lucas é focalizada a despedida de Jesus Cristo. Há um momento em que vai embora – vai adiante mas, há uma promessa. “Não vos deixarei órfãos.” Órfão é aquele que fica sozinho sem pai nem mãe.",
      "“Estarei convosco todos os dias até o fim do mundo.”",
