      "Na fé buscamos uma resposta para a vida e para a morte. Quem pode nos dizer alguma coisa para além desta vida? Só Deus e mais ninguém.",
      "E Deus disse tanta coisa.",
      "Dia dos Meios de Comunicação.",
      "Os Meios de Comunicação são a extensão da voz humana. Esta voz que chega há milhares de quilômetros. O Para fala em Roma e nós o ouvimos aqui. Há uma festa na China e nós participamos como se estivéssemos lá. Neste sentido o mundo se tornou uma pequena aldeia. Informações dos quatro cantos da terra chegam até nós e invadem nossas casas. Notícias em todas as áreas da atividade humana.",
