      "Homilia 136",
      "Quarta-Feira de Cinzas",
      "Nesta quarta-feira a liturgia inclui um pouco de cinza que é benta sobre o altar com a qual é feito o sinal da cruz X na testa dos fiéis e são ditas estas palavras: “convertei-vos e crede no Evangelho”, pelo celebrante. É uma proposta grandiosa, divina. Conversão significa voltar-se à Deus. Abandonar o mundo do pecado. Crer no Evangelho significa acolher a palavra de Deus e pô-la em prática. A cinza representa o fim de alguma coisa que estava viva. Podemos imaginar uma árvore que estava cheia de folhas, flores, frutos. Uma macieira, laranjeira, um pinheiro, etc.",
      "A árvore tem vida mas mais dia menos dia, ela morre e se transforma num punhado de cinza. Hoje muitas pessoas quando mortas são cremadas. Tudo se reduz a um pouco de cinza. Lembra isto as palavras da Bíblia sagrada que diz: “Lembra-te ó homem que és pó e em pó as de tornar”. Vira pó a matéria e não o espírito, a alma. O Deus que habita em nós é eterno. Muitas vezes um incêndio transforma um parque numa esteira de cinza.",
