      "A Palestina sempre foi um barril de pólvora. Sempre de novo foi, ainda hoje é, conquistada, invadida, destruída, seu povo escravizado, roubado, explorado e sempre de novo foi reconstruída. É uma história de sangue e cadáveres.",
