      "Homilia 147",
      "Povo de Deus",
      "Para o mundo cristão Jesus de Nazaré é o Filho de Deus, Senhor da vida e da história. Para o mundo pagão Jesus Cristo não tem importância nenhuma. Para algumas religiões Jesus é um grande Profeta.",
      "História",
      "Para o Povo de Deus.",
      "Em suas mãos está o destino último da vida. Ou a fé tem um alcance de vida eterna, de vida sem fim, ou será mais uma ilusão, mais um sonho, um devaneio, uma fantasia. E o Cristo também será um personagem comum, um falso profeta, um falso Deus, um ilusionista como tantos outros que se apagaram dentro do tempo. Mas surge a pergunta. Bilhões O seguem a mais de 20 séculos. Que algumas pessoas possam se enganar por algum tempo é possível. Mas que metade da humanidade hoje pudesse estar tão equivocada, iludida e tapeada isto é impossível. Seria um atestado de idiotice, de ignorância, de crendice e ingenuidade sem nenhum valor diante de um mundo cada vez mais científico, técnico e racional. Por outro lado, se Ele for deixado de lado depois desta experiência profunda de seguimento, de fé, de vida cristã, o que ou quem o substituirá. Quais são os valores do mundo em relação à vida e em relação à humanidade? Quem é o homem a partir do homem e das coisas materiais. Qual é o projeto de felicidade, de bem-estar, de prazer, poder, de justiça e de fraternidade humana que o mundo oferece? Não é o homem um lobo para o homem? Quanto armamento? Quantas guerras. Quanta violência, quanta miséria, quanta fome, quantas mortes prematuras? Como este mundo que está ali oferece alguma perspectiva de vida digna? Indo por este caminho, qual é o futuro que nos espera?",
