      "Homilia 173",
      "O que nos une",
      "O Domingo nos une.",
      "O Batizado nos une.",
      "O Advento nos une.",
      "Deus nos une.",
      "Poderíamos ser todos desconhecidos. Desconhecidos para sempre ou poderíamos ser apenas moradores de Piraquara.",
      "Poderíamos apenas termos encontrado na rua, na praça, no trabalho, no mercado ou pelos caminhos do mundo.",
      "No entanto neste domingo de manhã estamos juntos.",
      "Temos algo em comum: a nossa fé, a nossa esperança, que nos coloca junto lado a lado, frente à frente.",
      "E imaginamos nos encontrar mais um mundo de vezes assim como fizeram, e o fazem e o farão milhões de pessoas que viveram, que vivem e viverão depois de nós.",
      "A nossa fé nos faz celebrar o Advento que nos leva à Gruta de Belém e nos faz pensar no Natal.",
      "Não no Natal feito apenas de coisas deste mundo: enfeites, cartões, músicas, penduricalhos, ceia.",
      "Mas o Natal que tem por personagem fundamental o menino Deus – o Messias, o Salvador – Jesus Cristo.",
      "O Natal que nos apresenta um casal humilde (Maria e José).",
      "Natal que nos fala de pastores, de Reis magos, de anjos.",
      "Natal que envolve todo o Antigo Testamento e o novo também.",
      "Não celebramos uma historieta qualquer.",
      "Celebramos o acontecimento que mais marcou este mundo para sempre. Tanto que a humanidade começou a partir do nascimento desta criança, uma nova contagem da história: antes e depois Dele.",
      "Vale a pena estar aqui?",
      "Para muitos sim.",
      "Para muitos não.",
      "Para muita gente o Natal não tem grande importância. Ao longo da nossa vida perdemos tempo com tantas coisas fúteis que não constroem a nossa felicidade.",
      "Imaginar que todas as coisas deste mundo são mais importante do que a mensagem no Natal?  Se assim fosse os poderosos e milionários deveriam estar sempre de bem com a vida e com a história.",
      "Quantos reis, rainhas, soberanos, presidentes, artistas perderam o poder, foram presos ou assassinados. (Quanta coisa se fala de Herodes, de Nero, de Hitler, de Pinochet, etc...)",
      "Se deixarmos fora da nossa vida o Natal, que outro acontecimento nos encherá a alma e o espírito ao longo da nossa existência?"
