      "Jerusalém",
      "Epifania",
      "Jerusalém como capital do mundo capaz de reunir povos de todas as nações, onde está o templo de Salomão cheio de ouro e pedras preciosas, onde está a arca que continha as Tábuas da Lei revelada à Moisés, haveria agora com a chegada do Messias de resplandecer como luz.",
      "O Profeta Isaías imaginava uma Jerusalém toda iluminada, como a luz do sol. Porque chegou o Messias. As trevas, sinônimo de pecado – iniquidade, que envolvem a terra desaparecerão diante da glória do Senhor.",
      "- os povos agora caminham sob tua luz – o que significaria isto? Os reis caminham ante o clarão da aurora. As mais altas autoridades obedeceriam à Deus.",
