      "Como foi a caminhada de Maria de Nazaré?",
      "Foi uma caminhada humilde, corajosa, despojada, de fé, profética, dolorosa, triunfante.",
      "Caminhada humilde",
      "Não tinha Maria a vaidade das mulheres abastadas, poderosas, influentes e sábias da sua época.",
      "Maria era uma simples doméstica de Nazaré. Fazia parte do povo escolhido que esperava pela vinda do Messias. Fez as grandes coisas que uma boa mãe de família faz.",
      "Cuidou de um lar, de uma moradia, de uma criança, cuidou de José, o carpinteiro, seu esposo.",
      "Maria lavou o chão, roupa, acendeu o fogo, fez comida; enxugou louça, varreu a casa. Buscou água na fonte. Fez as grandes coisas que uma doméstica sabia fazer.",
      "Foi trabalhar de empregada na casa de Isabel “O Senhor fez em mim maravilhas...”",
