      "Disse sim ao anjo sem saber o quanto isto lhe custaria. “Faça-se a vontade de Deus”.",
      "Maria atravessou montanhas, vales, desertos. Calor de 40º , 50º graus. Animais selvagens – salteadores. Fez caminhada de mais de 300 km. Depois a volta. Maria enfrentou o ódio de Herodes que mandou matar todas as crianças de dois  anos para baixo. Mandou matar João Batista. Mandou matar toda sua família. Certamente mandou matar o Cristo também – Maria, uma mulher corajosa.",
