      "Frei Rui Guido Depiné o.f.m.",
      "Cristo como modelo de vida. Ele fez a melhor proposta. Ele tem a doutrina mais bela e a sabedoria mais profunda. Ninguém jamais falou como este homem (Herodes, Cesar Augusto Imperador de Roma, Anás, Pilatos, Caifaz eram deuses de barro ao lado de Cristo).",
