      "Assunção de Maria aos Céus",
      "Frei Rui Guido Depiné (o.f.m.)",
      "A Bíblia Sagrada nos fala em tantas páginas, em tantos momentos, que o destino último do homem não é o seu desaparecimento, sua destruição total – o seu fim definitivo – o seu aniquilamento onde no cemitério – na sepultura – uma infinidade de bactérias e o próprio tempo acabam com tudo.",
      "Diz a Bíblia: “Lembra-te homem que tu és pó e em pó as de tornar”.",
      "Esta afirmação tem sentido quando bem entendida. No cemitério acaba o que? A matéria. O espírito não é sepultado – o espírito não tem fim. Caminha para a sua plenitude. O espírito não é matéria.",
