      "Frei Rui Guido Depiné o.f.m.",
      "33 anos de idade. Passara toda sua vida pregando a paz, a justiça e a verdade, o Reino de Deus.",
      "Agora estava morto por ordem das mais altas autoridades e também por vontade popular. Este era o fim de mais um aventureiro que se intitulava “Filho de Deus”. Seu corpo estava destinado à fossa comum, se alguém não aparecesse para reclamar o cadáver. A lei romana não proibia que algum amigo ou parente o sepultasse.",
      "José de Arimatéia, membro do Sinédrio, amigo de Jesus, com coragem apresentou-se a Pilatos e pediu o corpo. Comprovada sua morte, o corpo foi liberado, ungido e sepultado. Uma pedra pesada fechava a entrada. Guardas vigiavam a sepultura.",
