      "A visita, a aparição de Jesus Cristo aos discípulos reunidos a porta fechada, trancados, fechados por medo dos judeus, transformam a vida dos discípulos confusos, tímidos, medrosos de serem identificados como seguidores do homem de Nazaré – agora com a presença do Cristo vivo são outros colaboradores. São novas criaturas. Não conhecem mais limites humanos. Vão pelo mundo afora, por toda a Palestina e pregam a doutrina de Jesus de Nazaré.",
