      "A casa de Deus",
      "Com a história de Jesus Cristo em nossas mãos – com a força do Espírito Santo, nós viemos das nossas casas para estar na Casa de Deus, em comunhão com todos.",
      "Queremos celebrar a nossa fé com toda humanidade que crê em Jesus Cristo – com todas as expressões de fé sem omitir ninguém. Até porque, quem julga é Deus.",
      "Grande parcela crê que Jesus Cristo é o caminho, a verdade e a vida e que ele é a ponte, o vínculo que nos leva ao Reino de Deus. Por que? Buscar as coisas de Deus? Para que tenhamos mais vida.  Os nossos antepassados nos legaram os ensinamentos de Cristo Jesus. Eles viveram sua fé e nos repassaram a grandiosidade desta crença e tornaram este mundo um pouco melhor. A história da Igreja é feita por todos os que creem em Cristo Jesus. É uma história misturada de luzes e sombras – de virtudes e pecados. É a partir de Jesus Cristo que muitos se deram e se dão as mãos. Alento do espírito de justiça e da solidariedade humana.",
      "Não obstante os limites e a pequenez do homem Deus sempre está presente e se revela.",
