      "Homilia 53",
      "Advento",
      "Espera – alimenta a esperança de algo novo. Quem espera crê em alguma verdade.",
      "Expectativa",
      "Chegada",
      "Vinda",
      "Acontecimento – sobrenatural",
      "Preparação – para as Festas de Natal",
      "Com o Advento iniciamos um novo tempo litúrgico em que lembramos historicamente a esperança do povo de Israel – Povo escolhido de ir ao encontro do Messias predito pelos Profetas – ansiosamente esperado pelo povo da Bíblia. Todas as esperanças humanas de um mundo mais justo e pacífico só poderia se concretizar a partir de um Messias. Este povo não acreditava mais em promessas humanas, cansado de ser enganado.",
      "Diziam: as palavras dos homens são vazias, as promessas também.",
