      "Homilia 54",
      "A quaresma e a vida",
      "Quaresma, um tempo especial onde meditamos sobre a vida, a morte e a Páscoa de Jesus Cristo.",
      "Buscamos no altar e na palavra de Deus o sentido maior desta vida.",
      "A vida humana como o bem mais precioso deste mundo. Como obra-prima de Deus. A vida que nunca em qualquer idade, em qualquer fase da existência, infância – adolescência – juventude – plena idade ou velhice nunca está pronta, nunca está acabada. A vida é uma construção permanente – uma permanente elaboração – uma permanente gestação – ensaio.",
      "A vida que pode ser bela, grandiosa, fascinante, feliz, fraterna, cheia de encantos e a vida que se comunica, a vida que se doa. A vida que é compartilhada. A vida que é solidária. A vida religiosa.",
      "A vida feita de sonhos, de projetos e de esperança.",
      "A vida que corre o risco de perder o seu sentido sagrado. A vida que se degrada de tanto tormento – que se torna violenta – bruta – cruel – indiferente – desumana – vazia. A vida que assusta e que mata a vida.",
      "O jejum tem que ter um sentido maior e não pode ser uma mera cerimônia ou gesto vazio."
