    "slug": "homilia-58-jesus-e-seus-discipulos",
    "titulo": "Homilia 58 Jesus e seus discípulos",
    "categoria": "Homilias",
    "data": "",
    "paragrafos": [
      "Homilia 58",
      "Jesus e seus discípulos",
      "Evangelho de 24/09/2006",
      "Neste domingo Jesus não está sozinho – num com uma grande multidão de povo.",
      "Ele está com um pequeno grupo de pessoas. Um grupo predileto, escolhido a dedo. São seus discípulos, colaboradores, seus amigos de confiança. Continuadores – sucessores seus, quando a morte levaria Jesus deste convívio. A obra de Jesus não poderia acabar com sua morte. Alguém deveria levar adiante sua memória, sua história, sua doutrina, seu projeto. Jesus Cristo não é somente um nome, mas um plano de vida, um projeto de vida, uma proposta de vida para toda a humanidade.",
      "Em vão os homens constroem a cidade dos homens se Deus não estiver junto. Isto está demonstrado ao longo de toda História Universal.",
      "A obra de Jesus Cristo deveria ter continuidade. Se Ele está morto ainda que ressuscitado quem daria continuidade à sua história? Seus amigos, os discípulos. Mas eles não tinham grande consciência, uma visão maior do Messias – de Jesus Cristo. Eles eram pessoas simples – sem muito conhecimento – cultura e instrução.",
      "Mas Jesus Cristo entendeu que eles eram estes prediletos.",
      "Por que eles foram convidados?",
      "Porque eles tinham tantas virtudes, tantas qualidades, como de: boa vontade, espírito de luta, desprendimento. Não eram escravos das coisas deste mundo. Nem mesquinhos, egoístas. Eram livres – despojados.",
      "Eles com facilidade, diante do convite, deixaram seus interesses, seus negócios, sua profissão, sua fantasia e mesmo limitados, inexperientes, com todos os seus limites humanos e pecados – mas também com sua boa vontade – suas virtudes, sua coragem, sua magnanimidade.",
      "Eles não eram doutores nem escribas. Não se formaram nas grandes escolas de Jerusalém – Nem no templo. Havia gente muito mais preparada, mais sábia, mais competente. Mas Jesus escolheu estes discípulos que estão nas páginas da Bíblia e não outros. Que entendiam eles da proposta de Jesus. Da sua doutrina. Da sua mensagem. Do seu Evangelho. Dos seus ensinamentos. Do Reino dos Céus ou do Reino de Deus. Entendiam pouco ou nada. Na medida da convivência iam pegando o jeito do Cristo, o espírito e a sabedoria do Cristo.",
      "Se estar junto do Cristo já era tarefa difícil segui-Lo, imaginem sem Ele. É sobre isto que Jesus fala. Vai chegar o dia em que Ele vai faltar. Ele será preso... os discípulos nem entendiam o que Ele queria dizer."
    ]
