      "Eles eram pessoas simples. Não tinham grande instrução – grande conhecimento – muita cultura. Mas foi a estes que o Cristo convidou. Porque eram pessoas de boa vontade, despojados dos bens – livres – não escravos de nada – deixaram a profissão – a família – negócios – interesses seus e O seguiram com seus limites humanos, com suas fraquezas mas também com suas virtudes.",
      "Estes discípulos não eram formados nas grandes escolas em Jerusalém. No Templo. Havia gente muito mais preparada – muito mais sábia – mais competente, mas Jesus escolheu estes discípulos que estão nas páginas da Bíblia e não outros.",
