      "Homilia 67",
      "Transfiguração II",
      "Nós vivemos todos os dias o fenômeno da transfiguração. Transfiguração é transformação. É mudança de feição. Mudança de conteúdo – de valores – de forma. Tudo se modifica. Nada neste mundo é igual.",
      "Muda a ciência, a tecnologia, a eletrônica, muda a meteorologia, muda a economia, muda a política, muda a arte, a educação, muda o esporte, muda a ideologia, os sentimentos humanos, as emoções, os sonhos, os projetos. Muda a moeda, as roupas, o comportamento. As pessoas mudam. Nascem, crescem, envelhecem, morrem. Nada é estável, é definitivo. A manhã sucede a tarde. A tarde sucede à noite. À noite sucede a madrugada. Do nascente ao poente. Uma estação sucede a outra. À chuva sucede o sol, do sol as trevas, da escuridão o dia. Um invento ao outro são superados. Da noite para o dia, celulares e computadores. A uma geração, outra geração. Vivemos uma permanente transfiguração. À vida sucede a morte. A morte sucede a vida.",
