      "Em algum lugar nós nascemos e algum lugar nós iremos morrer. Como iremos morrer. Em suas caminhadas Jesus se encontra com muita gente. Nesta hora Ele se encontra com um cego de nascença. Ele era um mendigo. Ainda hoje tem muitos pedintes e mendigos nos Templos da Palestina e pelo mundo inteiro.",
      "Era um dia de sábado. Num sábado era proibido socorrer alguém. Dar a mão. Ajudar um doente. Cuidar de uma pessoa nem que estivesse morrendo. São leis estupidas. Jesus vai na contramão. Jesus sentiu compaixão deste homem. Por que nasceu cego? Que culpa tinha de não enxergar? Por que os outros enxergam e Ele não? Será a vida justa para todo mundo? Em toda a sua vida, ele nunca vira a luz do sol. Nuca vira a beleza da natureza: as flores, a mata, a natureza, um pôr de sol, aurora, etc.",
      "Ele nunca vira alguém porque era cego de nascença. A primeira pessoa que ele vê é Jesus Cristo. Se ele não se encontrasse com Ele, ele teria nascido cego, viveria cego, e teria morrido cego.",
      "Jesus faz um grande milagre. Nenhum doutor da lei, nenhuma autoridade, nenhum sumo sacerdote tivera o poder de dar a visão a este cego. Jesus sim.",
