      "Para as autoridades religiosas, Jesus transgrediu a lei do sábado, criou um escândalo e foi identificado como um pecador porque não guardava o sábado.",
      "Era a mentalidade judaica que um cego doente, deficiente, miserável ou mesmo estrangeiro, eram malditos por Deus. Eram pecadores, eram abominados, eram castigados por Deus por causa de suas vidas anteriores.",
