      "Advento 1º. Domingo",
      "Advento – um tempo muito especial para o povo da Bíblia que esperava confiante pela chegada do Messias. Este povo esperou séculos e milênios. Como nasceu o povo da Bíblia? Nasceu da contemplação das tantas maravilhas do universo. Tanta beleza, tanto encanto, tanto esplendor, só poderia advir das mãos de Deus. O homem não criou a vida, a água, a luz, o oxigênio, o firmamento – as estrelas, o céu e a terra. Isto só poderia ser obra de Deus.",
      "Vendo também o homem tantos males – tanta injustiça – miséria – tanta exclusão – tantas mortes - tornando a vida insuportável – um fardo pesado demais – só Deus poderia criar um novo céu e uma nova terra. E o povo da Bíblia animado pelos profetas espera pela chegada do Messias.",
