      "Uma cerca eletrizada",
      "Uma área de segurança",
      "Passagem proibida.",
      "Cuidado aqui pode significar a vida. O não cuidado pode significar a morte.",
      "Cuidado aqui significa – alerta.",
      "Ficai atentos porque não sabeis quando chegará o momento.",
      "Não sabeis se será de madrugada, de manhã ou de tarde ou de noite.",
      "Isto nos diz que Deus é o Senhor da vida.",
      "Deus é o Senhor da história.",
