      "Um Mestre da Lei se encontra com Jesus. Lhe faz uma pergunta. Não é uma pergunta honesta, bem intencionada, respeitosa. Quis pôr Jesus em dificuldade. Era uma espécie de cilada. Este tipo de abordagem era comum. Diz ele: “Mestre, que devo fazer para ganhar como herança a vida eterna?”",
