      "Faz por ele tudo o que está ao seu alcance. Cuida de seus ferimentos. Coloca na montaria e o leva a uma pensão. Paga as despesas e deixa dito que na volta pagará por outras despesas a mais.",
      "Jesus faz o Mestre da Lei raciocinar: Disse-lhe Jesus “Qual dos 3 foi o próximo do homem que caiu nas mãos dos assaltantes?” E ele respondeu: “Aquele que usou de misericórdia com ele”.",
      "Jesus termina a conversa com estas palavras – “Orai e faz tu o mesmo.”",
